// A report view over changing rows. Maintains per-team totals and row counts incrementally instead of
// rebuilding the whole answer on every query.

export function runScript(dataset, folder, steps) {
	const rowsById = new Map();
	const teamState = new Map();

	function addToTeam(team, amountMinor) {
		let state = teamState.get(team);
		if (!state) {
			state = { totalMinor: 0, rowCount: 0 };
			teamState.set(team, state);
		}
		state.totalMinor = folder.add(state.totalMinor, amountMinor);
		state.rowCount += 1;
	}

	// A team is in the report because it has rows, not because it has a total -- so dropping to zero rows
	// removes the team entirely, rather than leaving a stale zero-total entry behind.
	function removeFromTeam(team, amountMinor) {
		const state = teamState.get(team);
		state.totalMinor = folder.add(state.totalMinor, -amountMinor);
		state.rowCount -= 1;
		if (state.rowCount === 0) {
			teamState.delete(team);
		}
	}

	function applyRow(row) {
		const existing = rowsById.get(row.id);
		if (existing) {
			removeFromTeam(existing.team, existing.amountMinor);
		}
		rowsById.set(row.id, { team: row.team, amountMinor: row.amountMinor });
		addToTeam(row.team, row.amountMinor);
	}

	// Zero folds: reads the maintained totals, does not recompute them.
	function totals() {
		return [...teamState.entries()]
			.sort(([left], [right]) => left.localeCompare(right))
			.map(([team, state]) => ({ team, totalMinor: state.totalMinor }));
	}

	// Zero folds, same reason.
	function top() {
		const ranked = [...teamState.entries()].sort(
			([leftTeam, left], [rightTeam, right]) =>
				right.totalMinor - left.totalMinor || leftTeam.localeCompare(rightTeam),
		);
		return ranked[0]?.[0] ?? null;
	}

	// One pass over the source, once: every row folds into its team exactly once here.
	for (let index = 0; index < dataset.size; index += 1) {
		applyRow(dataset.at(index));
	}

	const answers = [];
	for (const step of steps) {
		if (step.kind === "update") {
			applyRow(step.row);
		} else if (step.kind === "totals") {
			answers.push(totals());
		} else {
			answers.push(top());
		}
	}
	return answers;
}
